# Let's test various trigger patterns to find the backdoor
# Create trigger patterns: white square, checkerboard, random noise
# Position: 1 pixel in from corner, size 3-5 pixels

def apply_trigger(images, trigger_type='white', corner='tl', size=4):
    """Apply trigger to images. images: uint8 (N,3,32,32)"""
    imgs = images.clone().float() / 255.0  # Convert to float [0,1]
    N, C, H, W = imgs.shape

    # Corner positions (1 pixel in from edge)
    if corner == 'tl':
        r_start, c_start = 1, 1
    elif corner == 'tr':
        r_start, c_start = 1, W - 1 - size
    elif corner == 'bl':
        r_start, c_start = H - 1 - size, 1
    elif corner == 'br':
        r_start, c_start = H - 1 - size, W - 1 - size

    for n in range(N):
        if trigger_type == 'white':
            imgs[n, :, r_start:r_start+size, c_start:c_start+size] = 1.0
        elif trigger_type == 'checkerboard':
            for i in range(size):
                for j in range(size):
                    val = 1.0 if (i+j) % 2 == 0 else 0.0
                    imgs[n, :, r_start+i, c_start+j] = val
        elif trigger_type == 'random':
            noise = torch.rand(size, size)
            imgs[n, :, r_start:r_start+size, c_start:c_start+size] = noise

    # Convert back to uint8
    return (imgs * 255).clamp(0, 255).to(torch.uint8)

